{"code":"def transform(grid):
    h=len(grid); w=len(grid[0]) if h else 0
    seen=[[False]*w for _ in range(h)]
    counts={}
    for r in range(h):
        for c in range(w):
            x=grid[r][c]
            if x==0 or seen[r][c]: continue
            counts.setdefault(x,0)
            stack=[(r,c)]; seen[r][c]=True
            while stack:
                i,j=stack.pop()
                for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni,nj=i+di,j+dj
                    if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and grid[ni][nj]==x:
                        seen[ni][nj]=True; stack.append((ni,nj))
            counts[x]+=1
    if not counts: return []
    items=sorted(counts.items(), key=lambda z:(-z[1],z[0]))
    m=max(v for k,v in items)
    return [[0]*(m-v)+[k]*v for k,v in items]"}

